def choose_move(observation):
    def gv(key, default=None):
        try:
            return observation.get(key, default)
        except Exception:
            return default

    def clamp_step(v):
        if v > 0:
            return 1
        if v < 0:
            return -1
        return 0

    def pos(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            try:
                return [int(x[0]), int(x[1])]
            except Exception:
                return None
        if isinstance(x, dict):
            if "x" in x and "y" in x:
                try:
                    return [int(x["x"]), int(x["y"])]
                except Exception:
                    return None
        return None

    def first_pos(seq):
        if not seq:
            return None
        for item in seq:
            p = pos(item)
            if p is not None:
                return p
        return None

    def normalize_positions(v):
        if not v:
            return []
        if isinstance(v, dict):
            out = []
            for k in ("positions", "cells", "items", "resources", "targets"):
                if k in v:
                    out = normalize_positions(v.get(k))
                    if out:
                        return out
            return [p for p in [pos(v)] if p is not None]
        if isinstance(v, (list, tuple)):
            out = []
            for item in v:
                p = pos(item)
                if p is not None:
                    out.append(p)
            return out
        p = pos(v)
        return [p] if p is not None else []

    sx, sy = 0, 0
    sp = pos(gv("self_position"))
    if sp is not None:
        sx, sy = sp[0], sp[1]

    op = pos(gv("opponent_position"))
    ox, oy = (op[0], op[1]) if op is not None else (None, None)

    w = gv("grid_width", gv("width", 0))
