    except Exception:
        h = 0

    env = gv("environment_name", gv("env_name", "resource_collection"))
    role = gv("self_role", "pursuer")

    def move_toward(tx, ty):
        return [clamp_step(tx - sx), clamp_step(ty - sy)]

    def move_away(tx, ty):
        return [clamp_step(sx - tx), clamp_step(sy - ty)]

    def dist(a, b, c, d):
        return abs(a - c) + abs(b - d)

    # Threat / safety heuristic
    if ox is not None and oy is not None:
        d_opp = dist(sx, sy, ox, oy)
    else:
        d_opp = 999999

