            if w > 0 and h > 0:
                cx, cy = w // 2, h // 2
                if d_opp <= 2 and ox is not None and oy is not None:
                    return move_away(ox, oy)
                return move_toward(cx, cy)
            return [0, 0]
        # Prefer nearest target, but if opponent is close, prefer one farther from opponent
        best = None
        best_score = None
